//! The prompt string table (STRINGS.DAT). Built-in defaults are the stock
//! r5 strings; `strings.toml` overrides any of them by name.

use std::collections::HashMap;
use std::path::Path;

use anyhow::Context;

/// Stock strings, generated by `iniquity import` from a stock install.
const STOCK: &str = include_str!("../assets/strings.toml");

#[derive(Clone)]
pub struct Strings {
    map: HashMap<String, String>,
    stock: HashMap<String, String>,
}

/// r5 strings that were numbered before they had names; overrides
/// saved under the old names still apply.
fn renamed(old: &str) -> Option<&'static str> {
    let n: usize = old.strip_prefix('s')?.parse().ok()?;
    const NODE: [&str; 12] = [
        "MNCyouspeak", "MNCtheyspeak", "MNCenterchat", "MNCquitchat", "NodeAskNode", "NodeUserOn",
        "NodeMsgAskText", "NodeMsgSent", "NodeMsgReceived", "NodeBCaskText", "NodeBCsent", "NodeBCreceived",
    ];
    NODE.get(n.checked_sub(287)?).copied()
}

/// Every string's name, in the stock table's order (STRINGS.DAT's).
pub fn stock_names() -> Vec<&'static str> {
    STOCK.lines().filter_map(|l| l.split_once(" = ").map(|(n, _)| n.trim())).filter(|n| !n.starts_with('#')).collect()
}

impl Strings {
    pub fn load(path: &Path) -> anyhow::Result<Self> {
        let stock: HashMap<String, String> = toml::from_str(STOCK).context("built-in strings")?;
        let mut map = stock.clone();
        match std::fs::read_to_string(path) {
            Ok(s) => {
                let over: HashMap<String, String> =
                    toml::from_str(&s).with_context(|| format!("parsing {}", path.display()))?;
                map.extend(over.into_iter().map(|(k, v)| (renamed(&k).map_or(k, String::from), v)));
            }
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
            Err(e) => return Err(e).with_context(|| format!("reading {}", path.display())),
        }
        Ok(Self { map, stock })
    }

    pub fn set(&mut self, name: &str, text: String) {
        self.map.insert(name.to_string(), text);
    }

    /// The strings that differ from stock, in stock order (what
    /// strings.toml holds).
    pub fn overrides(&self) -> Vec<(String, String)> {
        stock_names()
            .into_iter()
            .filter_map(|n| self.map.get(n).filter(|v| self.stock.get(n) != Some(*v)).map(|v| (n.to_string(), v.clone())))
            .collect()
    }

    /// `mStr`: a string by its original name (`strPause` -> `"Pause"`).
    pub fn get(&self, name: &str) -> &str {
        debug_assert!(self.map.contains_key(name), "unknown string {name}");
        self.map.get(name).map_or("", String::as_str)
    }

    /// `strCode`: a string with `%S1`, `%S2`... replaced by `args`.
    pub fn fmt(&self, name: &str, args: &[&str]) -> String {
        substitute(self.get(name), args)
    }
}

pub fn substitute(s: &str, args: &[&str]) -> String {
    let mut out = s.to_string();
    for (i, a) in args.iter().enumerate() {
        for tag in [format!("%S{}", i + 1), format!("%s{}", i + 1)] {
            out = out.replace(&tag, a);
        }
    }
    out
}

/// Write a string table as TOML, one `Name = "text"` per line, in order.
pub fn to_toml(entries: &[(String, String)]) -> String {
    let mut out = String::from(
        "# Iniquity prompt strings (STRINGS.DAT). Names are the original\n\
         # str* constants; r5 additions without one are numbered.\n\n",
    );
    for (name, text) in entries {
        out.push_str(&format!("{name} = {}\n", toml::Value::String(text.clone())));
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn stock_strings_parse() {
        let s = Strings::load(Path::new("/nonexistent")).unwrap();
        assert!(s.get("Pause").contains("use"));
        assert!(s.fmt("InvalidMnuCmd", &["ZZ"]).contains("ZZ"));
    }

    #[test]
    fn names_and_overrides() {
        let names = stock_names();
        assert_eq!(names.first(), Some(&"DetectEmu"));
        let mut s = Strings::load(Path::new("/nonexistent")).unwrap();
        assert_eq!(names.len(), s.map.len(), "every stock string is listed");
        assert!(s.overrides().is_empty());
        s.set("Pause", "wait".into());
        assert_eq!(s.overrides(), [("Pause".to_string(), "wait".to_string())]);
    }

    #[test]
    fn old_numbered_names_still_apply() {
        assert_eq!(renamed("s295"), Some("NodeMsgReceived"));
        assert_eq!(renamed("s286"), None);
        assert_eq!(renamed("Pause"), None);
    }

    #[test]
    fn substitutes_both_cases() {
        assert_eq!(substitute("%S1 and %s2", &["a", "b"]), "a and b");
    }
}
